1	// The constructor keeps public named params (`remoteDataSource`,
2	// `entriesBox`) distinct from the private fields they initialize, matching
3	// `account_settings_repository_impl.dart`'s documented convention.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:fpdart/fpdart.dart';
6	import 'package:hive_ce/hive_ce.dart';
7	
8	import '../../../../core/failure/failure.dart';
9	import '../../../../core/utils/deduped_by_id.dart';
10	import '../../domain/entities/entries_page.dart';
11	import '../../domain/entities/entry.dart';
12	import '../../domain/repositories/entries_repository.dart';
13	import '../datasources/entries_remote_data_source.dart';
14	import '../models/entry_dto.dart';
15	
16	/// On success, writes the entry through to the `entries` Hive box (`Box
17	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
18	/// returning `right(...)`, same "persist then return" ordering
19	/// `AuthRepositoryImpl._authenticate` already uses for its own
20	/// post-success side effect.
21	class EntriesRepositoryImpl implements EntriesRepository {
22	  EntriesRepositoryImpl({
23	    required EntriesRemoteDataSource remoteDataSource,
24	    required Box<Map> entriesBox,
25	  }) : _remoteDataSource = remoteDataSource,
26	       _entriesBox = entriesBox;
27	
28	  final EntriesRemoteDataSource _remoteDataSource;
29	  final Box<Map> _entriesBox;
30	
31	  @override
32	  Future<Either<Failure, Entry>> create({
33	    required String content,
34	    required EntrySource source,
35	    int? mediaDurationSeconds,
36	  }) async {
37	    final result = await _remoteDataSource.create(
38	      content: content,
39	      source: source,
40	      mediaDurationSeconds: mediaDurationSeconds,
41	    );
42	    return result.match((failure) async => left(failure), (dto) async {
43	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
44	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
45	      // own local-persistence step.
46	      try {
47	        await _entriesBox.put(dto.id, dto.toJson());
48	      } catch (error) {
49	        return left(Failure.malformedResponse(message: error.toString()));
50	      }
51	      return right(_toEntry(dto));
52	    });
53	  }
54	
55	  @override
56	  Future<Either<Failure, EntriesPage>> list({
57	    String? cursor,
58	    int limit = 20,
59	    EntrySource? source,
60	    DateTime? dateFrom,
61	    DateTime? dateTo,
62	  }) async {
63	    final result = await _remoteDataSource.list(
64	      cursor: cursor,
65	      limit: limit,
66	      source: source,
67	      dateFrom: dateFrom,
68	      dateTo: dateTo,
69	    );
70	    return result.match(
71	      (failure) async {
72	        // Boundaries/Design Notes: the Hive-cache fallback is scoped to
73	        // `cursor == null` (the first/fresh page) only — a paginated
74	        // continuation (`cursor != null`) that fails with
75	        // `networkOffline`/`networkTimeout` propagates as `Left` like any
76	        // other pagination failure instead, so `MeusRegistrosCubit`'s own
77	        // `loadMoreFailed`/retry path handles it uniformly rather than a
78	        // full unrelated cache dump silently replacing the in-progress
79	        // paginated list (and breaking its newest-first ordering).
80	        if (cursor == null &&
81	            (failure is NetworkOffline || failure is NetworkTimeout)) {
82	          return _offlineFallback();
83	        }
84	        return left(failure);
85	      },
86	      (page) async {
87	        try {
88	          await _entriesBox.putAll({
89	            for (final dto in page.items) dto.id: dto.toJson(),
90	          });
91	        } catch (error) {
92	          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
93	          // thrown Hive/disk exception must never escape unmapped.
94	          return left(Failure.malformedResponse(message: error.toString()));
95	        }
96	        return right(
97	          EntriesPage(
98	            items: page.items.map(_toEntry).toList(),
99	            nextCursor: page.nextCursor,
100	          ),
101	        );
102	      },
103	    );
104	  }
105	
106	  @override
107	  Future<Either<Failure, Entry>> getById(String id) async {
108	    final result = await _remoteDataSource.get(id);
109	    return result.match(
110	      (failure) async {
111	        // Boundaries: scoped to networkOffline/networkTimeout specifically
112	        // — every other Failure (notFound included) propagates as Left,
113	        // unmapped, same convention `list()`'s own cursor-scoped fallback
114	        // above uses.
115	        if (failure is NetworkOffline || failure is NetworkTimeout) {
116	          return _cachedEntryOrOriginalFailure(id, failure);
117	        }
118	        return left(failure);
119	      },
120	      (dto) async {
121	        // Same RNF09 rationale as `create()`/`list()`'s own Hive-write
122	        // guards — a thrown Hive/disk exception must never escape
123	        // unmapped.
124	        try {
125	          await _entriesBox.put(dto.id, dto.toJson());
126	        } catch (error) {
127	          return left(Failure.malformedResponse(message: error.toString()));
128	        }
129	        return right(_toEntry(dto));
130	      },
131	    );
132	  }
133	
134	  @override
135	  Future<Either<Failure, List<Entry>>> search(
136	    String query, {
137	    EntrySource? source,
138	    DateTime? dateFrom,
139	    DateTime? dateTo,
140	  }) async {
141	    final result = await _remoteDataSource.search(
142	      query,
143	      source: source,
144	      dateFrom: dateFrom,
145	      dateTo: dateTo,
146	    );
147	    return result.match(
148	      (failure) async {
149	        // Boundaries/AD-9: no cache fallback for search, unlike
150	        // list()/getById() — every Failure (including
151	        // networkOffline/networkTimeout) propagates as Left, unmapped.
152	        return left(failure);
153	      },
154	      (dtos) async {
155	        // Review finding: de-duplicated by id first (first-occurrence-wins,
156	        // same semantics as `MeusRegistrosCubit`'s own trust-but-verify
157	        // convention for server data, shared via `core/utils/
158	        // deduped_by_id.dart`) — so the `putAll` below and the returned
159	        // list stay consistent, and `_SearchResults`' `ListView.builder`
160	        // (keyed by `ValueKey(entry.id)`) never sees a duplicate key even
161	        // if the backend ever violated its own no-duplicate-ids invariant.
162	        final dedupedDtos = dedupedById(dtos, (dto) => dto.id);
163	        // Same RNF09 rationale as create()/list()/getById()'s own
164	        // Hive-write guards — a thrown Hive/disk exception must never
165	        // escape unmapped.
166	        try {
167	          await _entriesBox.putAll({
168	            for (final dto in dedupedDtos) dto.id: dto.toJson(),
169	          });
170	        } catch (error) {
171	          return left(Failure.malformedResponse(message: error.toString()));
172	        }
173	        return right(dedupedDtos.map(_toEntry).toList());
174	      },
175	    );
176	  }
177	
178	  /// [getById]'s own offline/timeout fallback (Boundaries): a cache hit
179	  /// returns `Right` from the cached `EntryDto`; a cache miss propagates
180	  /// [originalFailure] unchanged — "no synthesized not-found" — rather than
181	  /// inventing a [Failure.notFound] this repository never actually
182	  /// received from the backend. A corrupt cached entry (should never
183	  /// happen — every entry here was written by [create]/[list]/[getById]
184	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
185	  /// (RNF09), same guard `_offlineFallback()`'s own malformed-cache check
186	  /// uses.
187	  Either<Failure, Entry> _cachedEntryOrOriginalFailure(
188	    String id,
189	    Failure originalFailure,
190	  ) {
191	    try {
192	      final cached = _entriesBox.get(id);
193	      if (cached == null) {
194	        return left(originalFailure);
195	      }
196	      return right(
197	        _toEntry(EntryDto.fromJson(Map<String, dynamic>.from(cached))),
198	      );
199	    } catch (error) {
200	      return left(Failure.malformedResponse(message: error.toString()));
201	    }
202	  }
203	
204	  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
205	  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
206	  /// dump has no further page to request. A corrupt cached entry (should
207	  /// never happen — every entry here was written by [create]/[list]
208	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
209	  /// (RNF09), same guard `create()`'s own Hive write already has.
210	  Either<Failure, EntriesPage> _offlineFallback() {
211	    try {
212	      final entries =
213	          _entriesBox.values
214	              .map(
215	                (json) => _toEntry(
216	                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
217	                ),
218	              )
219	              .toList()
220	            ..sort(
221	              (a, b) =>
222	                  DateTime.parse(b.occurredAt)
223	                      .compareTo(DateTime.parse(a.occurredAt)),
224	            );
225	      return right(EntriesPage(items: entries, nextCursor: null));
226	    } catch (error) {
227	      return left(Failure.malformedResponse(message: error.toString()));
228	    }
229	  }
230	
231	  Entry _toEntry(EntryDto dto) => Entry(
232	    id: dto.id,
233	    content: dto.content,
234	    source: dto.source,
235	    chatMessageId: dto.chatMessageId,
236	    occurredAt: dto.occurredAt,
237	    serverRevision: dto.serverRevision,
238	    createdAt: dto.createdAt,
239	    updatedAt: dto.updatedAt,
240	    mediaDurationSeconds: dto.mediaDurationSeconds,
241	  );
242	}
