429	  void _onPhotoStateChange(BuildContext context, PhotoCaptureState state) {
430	    if (state is PhotoRecognized && state.path != _lastSyncedPhotoPath) {
431	      _lastSyncedPhotoPath = state.path;
432	      _photoTextController.text = state.text;
433	    }
434	    final kind = _photoAnnounceKindOf(state);
435	    if (kind == _lastPhotoAnnouncedKind) {
436	      return;
437	    }
438	    _lastPhotoAnnouncedKind = kind;
439	    switch (state) {
440	      case PhotoProcessing():
441	        _announce('Reconhecendo texto da foto');
442	      case PhotoRecognized(saving: true):
443	        _announce('Salvando registro');
444	      case PhotoRecognized():
445	        _announce('Texto reconhecido. Revise o texto antes de salvar.');
446	      case PhotoError(message: final message):
447	        _announce(message);
448	      case PhotoSaved():
449	        // Same "wait for the announcement" rationale as
450	        // `TextEntrySaved`/`AudioSaved` above.
451	        unawaited(
452	          _announce('Registro salvo').then((_) {
453	            if (context.mounted) {
454	              _unfocusAndPop(context);
455	            }
456	          }),
457	        );
458	      case PhotoIdle():
459	        // Reachable via `cancel()` resetting from `PhotoProcessing` (a
460	        // tab switch away mid-pick/mid-OCR), same rationale as
461	        // `AudioIdle`'s own "Gravação cancelada" above.
462	        _announce('Captura de foto cancelada');
