      return;
    }
    if (isClosed) {
      return;
    }
    emit(const ChatBootstrapLoading());

    final sessionsResult = await _repository.listSessions();
    if (isClosed) {
      return;
    }
    final sessionResult = await sessionsResult.match(
      (failure) async => Left<dynamic, ChatSession>(failure),
      (sessions) async {
        if (sessions.isEmpty) {
          return _repository.createSession();
        }
        // "reuse the most recent" — defensively re-sorts rather than
        // trusting `listSessions()`'s own ordering (its offline-cache
        // fallback already sorts `updatedAt` desc, but the live server
        // response's own ordering isn't documented either way).
        final mostRecent = [...sessions]
          ..sort((a, b) => b.updatedAt.compareTo(a.updatedAt));
        return Right<dynamic, ChatSession>(mostRecent.first);
      },
    );
