            if (!completer.isCompleted) {
              completer.complete();
            }
          },
          onDone: () {
            if (!completer.isCompleted) {
              completer.complete();
            }
          },
          cancelOnError: false,
        );
    await completer.future;
  }

  void _applyStreamEvent(String aiMessageId, ChatStreamEvent event) {
    if (isClosed) {
      return;
    }
    final current = state;
    if (current is! ChatReady) {
      return;
    }
