      personaSnapshot: $enumDecode(
        _$ChatPersonaEnumMap,
        json['personaSnapshot'],
      ),
      userMessageCount: (json['userMessageCount'] as num).toInt(),
      lastUserMessageAt: json['lastUserMessageAt'] as String?,
      createdAt: json['createdAt'] as String,
      updatedAt: json['updatedAt'] as String,
    );

Map<String, dynamic> _$ChatSessionDtoToJson(ChatSessionDto instance) =>
    <String, dynamic>{
      'id': instance.id,
      'title': instance.title,
      'personaSnapshot': _$ChatPersonaEnumMap[instance.personaSnapshot]!,
      'userMessageCount': instance.userMessageCount,
      'lastUserMessageAt': instance.lastUserMessageAt,
      'createdAt': instance.createdAt,
      'updatedAt': instance.updatedAt,
    };

const _$ChatPersonaEnumMap = {
  ChatPersona.analitico: 'analitico',
  ChatPersona.empatico: 'empatico',
  ChatPersona.socratico: 'socratico',
};
