          .thenAnswer((_) => stream);

      expect(repository.sendMessage('s1', 'hi'), stream);
      verifyNever(() => mockMessagesBox.put(any(), any()));
      verifyNever(() => mockMessagesBox.putAll(any()));
    });
  });
}

